"use client"

import { useEffect, useState } from "react"
import { StatCard } from "@/components/stat-card"
import { useAuth } from "@/app/context/auth-context"
import { UserRole } from "@/lib/auth"
import { Users, DollarSign, Calendar, UserCheck, Building2, Car, MapPin, Clock } from "lucide-react"
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card"
import { dashboardService, DashboardStats } from "@/lib/services/dashboard-service"
import {
  Bar, BarChart, ResponsiveContainer, XAxis, YAxis, Tooltip,
  PieChart, Pie, Cell, Legend
} from "recharts"
import { format } from "date-fns"
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { userService } from "@/lib/services/user-service"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { User as UserIcon, Percent, Receipt } from "lucide-react"

import { PageHeader } from "@/components/layouts/page-header"
import { cn } from "@/lib/utils"
import { PERMISSIONS } from "@/lib/permissions"

export default function DashboardPage() {
  const { user, canAccess, hasPermission } = useAuth()
  const [stats, setStats] = useState<DashboardStats | null>(null)
  const [loading, setLoading] = useState(true)
  const [chartPeriod, setChartPeriod] = useState<"weekly" | "monthly" | "yearly">("weekly")
  const [managerFilter, setManagerFilter] = useState<string>("ALL")
  const [managers, setManagers] = useState<any[]>([])

  useEffect(() => {
    loadStats()
  }, [user, managerFilter])

  useEffect(() => {
    if (user && (user.role === UserRole.SYSTEM_SUPER_ADMIN || user.role === UserRole.PARKING_SUPER_ADMIN)) {
      loadManagers()
    }
  }, [user])

  const loadManagers = async () => {
    try {
      const res = await userService.getAllUsers({
        role: UserRole.PARKING_MANAGER,
        orgId: user?.orgId && user.role !== UserRole.SYSTEM_SUPER_ADMIN ? user.orgId : undefined
      })
      const userList = res.data || res.users
      if (userList) setManagers(userList)
    } catch (err) {
      console.error("Failed to load managers", err)
    }
  }

  const loadStats = async () => {
    if (!user) return
    try {
      setLoading(true)
      const data = await dashboardService.getDashboardStats({
        managerUserId: managerFilter === "ALL" ? undefined : managerFilter
      })
      setStats(data)
    } catch (error) {
      console.error(error)
    } finally {
      setLoading(false)
    }
  }

  if (loading || !stats) {
    return <div className="p-6">Loading dashboard...</div>
  }

  // --- STAT CARDS ---
  const statCards = [
    {
      icon: <Calendar size={24} />,
      label: "Total Bookings",
      value: stats.totalBookings,
      change: 0,
      description: "lifetime reservations",
      show: hasPermission(PERMISSIONS.DASHBOARD_TOTAL_BOOKINGS)
    },
    {
      icon: <DollarSign size={24} />,
      label: "Total Revenue",
      value: `${stats.revenue.toLocaleString()} ETB`,
      change: 0,
      description: "gross earnings",
      show: hasPermission(PERMISSIONS.DASHBOARD_TOTAL_REVENUE)
    },
    {
      icon: <Percent size={24} />,
      label: "Total Commission",
      value: `${(stats.commission || 0).toLocaleString()} ETB`,
      change: 0,
      description: "platform's cut",
      show: hasPermission(PERMISSIONS.REVENUE_VIEW)
    },
    {
      icon: <Receipt size={24} />,
      label: "Total VAT",
      value: `${(stats.vat || 0).toLocaleString()} ETB`,
      change: 0,
      description: "tax collected",
      show: hasPermission(PERMISSIONS.REVENUE_VIEW)
    },
    {
      icon: <UserCheck size={24} />,
      label: "Staff Users",
      value: stats.totalSystemAdmins,
      change: 0,
      description: "PossibleTech admins",
      show: user?.role === UserRole.SYSTEM_SUPER_ADMIN || user?.role === UserRole.SYSTEM_ADMIN
    },
    {
      icon: <Building2 size={24} />,
      label: "Parking Users",
      value: stats.totalParkingStaff,
      change: 0,
      description: "Admins & Managers",
      show: hasPermission(PERMISSIONS.USER_VIEW)
    },
    {
      icon: <MapPin size={24} />,
      label: "Total Parkings",
      value: stats.totalParkings,
      change: 0,
      description: "registered facilities",
      show: hasPermission(PERMISSIONS.PARKING_VIEW)
    },
    {
      icon: <Car size={24} />,
      label: "Active Parkings",
      value: stats.activeParkings,
      change: 0,
      description: "currently operational",
      show: hasPermission(PERMISSIONS.PARKING_VIEW)
    },
    {
      icon: <Clock size={24} />,
      label: "Pending Parkings",
      value: stats.pendingParkings,
      change: 0,
      description: "awaiting approval",
      show: user?.role === UserRole.SYSTEM_SUPER_ADMIN || user?.role === UserRole.SYSTEM_ADMIN
    }
  ];

  // --- CHART DATA ---
  const currentChartData = stats.trends[chartPeriod];

  return (
    <div className="p-6 space-y-6">
      <PageHeader
        title="Dashboard"
        description={canAccess([UserRole.SYSTEM_SUPER_ADMIN]) ? "Global System Overview" : "Parking Analytics Overview"}
      >
        {(user?.role === UserRole.SYSTEM_SUPER_ADMIN || user?.role === UserRole.PARKING_SUPER_ADMIN) && managers.length > 0 && (
          <div className="flex items-center gap-3">
            <span className="text-sm font-bold text-slate-500 hidden sm:inline">Filter Manager:</span>
            <Select value={managerFilter} onValueChange={setManagerFilter}>
              <SelectTrigger className="w-[180px] h-11 rounded-xl border-slate-200 bg-white">
                <div className="flex items-center gap-2 truncate">
                  <UserIcon className="h-4 w-4 text-slate-400 shrink-0" />
                  <SelectValue placeholder="All Managers" />
                </div>
              </SelectTrigger>
              <SelectContent className="rounded-xl">
                <SelectItem value="ALL">All Managers</SelectItem>
                {managers.map((m) => (
                  <SelectItem key={m.id} value={m.id}>
                    {m.fullName}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        )}
      </PageHeader>

      {/* 1. METRICS GRID */}
      <div className={cn(
        "grid gap-6",
        statCards.filter(s => s.show).length > 3 ? "grid-cols-1 md:grid-cols-2 lg:grid-cols-4" : "grid-cols-1 md:grid-cols-3"
      )}>
        {statCards.filter(s => s.show).map((stat, index) => (
          <StatCard key={index} {...stat} />
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-7 gap-6">

        {/* 3. PAYMENT METHOD PIE CHART */}
        {hasPermission(PERMISSIONS.REVENUE_VIEW) && (
          <Card className="col-span-1 lg:col-span-3 min-h-[400px]">
            <CardHeader>
              <CardTitle>Payment Methods</CardTitle>
              <CardDescription>Distribution by transaction volume</CardDescription>
            </CardHeader>
            <CardContent>
              <div className="h-[300px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={stats.paymentStats}
                      cx="50%"
                      cy="50%"
                      innerRadius={80}
                      outerRadius={100}
                      paddingAngle={5}
                      dataKey="value"
                      stroke="hsl(var(--background))"
                      strokeWidth={2}
                    >
                      {stats.paymentStats?.map((entry: any, index: number) => (
                        <Cell
                          key={`cell-${index}`}
                          fill="var(--primary)"
                          fillOpacity={1 - (index * 0.15)}
                        />
                      ))}
                    </Pie>
                    <Tooltip
                      contentStyle={{
                        borderRadius: '8px',
                        border: '1px solid hsl(var(--border))',
                        backgroundColor: 'hsl(var(--background))'
                      }}
                    />
                    <Legend verticalAlign="bottom" height={36} iconType="circle" />
                  </PieChart>
                </ResponsiveContainer>
              </div>
            </CardContent>
          </Card>
        )}

        {/* 2. MAIN TRENDS CHART */}
        <Card className={cn(
          "col-span-1 min-h-[400px]",
          hasPermission(PERMISSIONS.REVENUE_VIEW) ? "lg:col-span-4" : "lg:col-span-7"
        )}>
          <CardHeader className="flex flex-col sm:flex-row items-start sm:items-center justify-between pb-2">
            <div>
              <CardTitle>Booking Trends</CardTitle>
              <CardDescription>Revenue volume over time</CardDescription>
            </div>
            <Tabs defaultValue="weekly" value={chartPeriod} onValueChange={(v) => setChartPeriod(v as any)} className="mt-2 sm:mt-0">
              <TabsList>
                {hasPermission(PERMISSIONS.DASHBOARD_DAILY_STATS) && <TabsTrigger value="weekly">Weekly</TabsTrigger>}
                {hasPermission(PERMISSIONS.DASHBOARD_MONTHLY_STATS) && <TabsTrigger value="monthly">Monthly</TabsTrigger>}
                {hasPermission(PERMISSIONS.DASHBOARD_YEARLY_STATS) && <TabsTrigger value="yearly">Yearly</TabsTrigger>}
              </TabsList>
            </Tabs>
          </CardHeader>
          <CardContent>
            <div className="h-[300px] w-full mt-4">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={currentChartData}>
                  <XAxis
                    dataKey="name"
                    stroke="#888888"
                    fontSize={12}
                    tickLine={false}
                    axisLine={false}
                  />
                  <YAxis
                    stroke="#888888"
                    fontSize={12}
                    tickLine={false}
                    axisLine={false}
                    tickFormatter={(value) => `${value}`}
                  />
                  <Tooltip
                    cursor={{ fill: 'var(--muted)', opacity: 0.2 }}
                    contentStyle={{
                      borderRadius: '8px',
                      border: '1px solid hsl(var(--border))',
                      boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
                      backgroundColor: 'hsl(var(--background))'
                    }}
                  />
                  <Bar
                    dataKey="total"
                    fill="var(--primary)"
                    radius={[4, 4, 0, 0]}
                    name="Revenue (ETB)"
                    barSize={40}
                  />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* 4. RECENT ACTIVITY */}
      {hasPermission(PERMISSIONS.BOOKING_VIEW) && (
        <Card>
          <CardHeader>
            <CardTitle>Recent Activity</CardTitle>
            <CardDescription>Latest bookings across the system</CardDescription>
          </CardHeader>
          <CardContent>
            <div className="space-y-6">
              {stats.recentBookings && stats.recentBookings.length > 0 ? (
                stats.recentBookings.map((booking: any) => (
                  <div key={booking.id} className="flex items-center justify-between border-b last:border-0 pb-4 last:pb-0">
                    <div className="flex items-center gap-4">
                      <div className="h-10 w-10 rounded-full bg-primary/10 flex items-center justify-center">
                        <UserCheck className="h-5 w-5 text-primary" />
                      </div>
                      <div className="space-y-1">
                        <p className="text-sm font-medium">{booking.customerName}</p>
                        <p className="text-xs text-muted-foreground">{booking.plateNumber} • {booking.paymentMethod}</p>
                      </div>
                    </div>
                    <div className="text-right">
                      <p className="font-medium text-sm">+ {booking.totalAmount} ETB</p>
                      <p className="text-xs text-muted-foreground">{format(new Date(booking.createdAt || new Date()), "MMM d, h:mm a")}</p>
                    </div>
                  </div>
                ))
              ) : (
                <p className="text-muted-foreground text-center py-4">No recent bookings found.</p>
              )}
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}
